contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    receive() external payable {}

    function run(bytes32 guess, uint lockAmount, uint settleDelay) public payable {
        require(lockAmount == 1 ether, "lockAmount must be 1 ether");
        require(address(this).balance >= lockAmount, "insufficient balance");

        c.lockInGuess{value: lockAmount}(guess);

        uint targetBlock;
        assembly {
            targetBlock := add(number(), 1)
        }
        uint beforeBalance = address(c).balance;

        bool locked = targetBlock != 0;

        bool settled;
        bool reverted;
        if (block.number >= targetBlock) {
            try c.settle() { settled = true; reverted = false; } catch { settled = false; reverted = true; }
        }

        uint afterBalance = address(c).balance;
        bool lostEther = afterBalance < beforeBalance;
        bytes32 computedAnswer = keccak256(abi.encodePacked(blockhash(targetBlock)));
        bool guessMatches = guess == computedAnswer;

        assert(!locked || !settled || (!reverted && (lostEther == guessMatches)));
    }
}

