contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(bytes32 h) public payable {
        require(address(this).balance >= 1 ether);
        uint expectedBlock = block.number + 1;
        c.lockInGuess{value: 1 ether}(h);
        assert(_storedBlock() == expectedBlock && _storedGuess() == h);
    }
    function _storedBlock() internal view returns (uint) {
        return _guessBlock();
    }
    function _storedGuess() internal view returns (bytes32) {
        return _guessHash();
    }
    function _guessBlock() internal view returns (uint) {
        (bool success, bytes memory data) = address(c).staticcall(abi.encodeWithSignature("guesses(address)", address(this)));
        if (!success) return 0;
        if (data.length < 64) return 0;
        return abi.decode(data, (uint));
    }
    function _guessHash() internal view returns (bytes32) {
        (bool success, bytes memory data) = address(c).staticcall(abi.encodeWithSignature("guesses(address)", address(this)));
        if (!success) return bytes32(0);
        if (data.length < 64) return bytes32(0);
        return abi.decode(data, (bytes32));
    }
    receive() external payable {}
}

